"""Tests for the Session-Bench publication import boundary."""
from __future__ import annotations

import subprocess
import sys
from pathlib import Path


REPO = Path(__file__).resolve().parents[2]
SCRIPT = REPO / "scripts" / "sync_session_bench.py"
HOSTED = REPO / "docs" / "_data" / "session_bench.yml"


def canonical_artifact() -> bytes:
    return (
        "# GENERATED by scripts/evaluate.py — do not hand-edit.\n"
        "# Inputs: data/measurements.json + data/verdicts.yml.\n"
        "generated_by: scripts/evaluate.py\n"
        "source_repository: https://github.com/jazzyalex/session-bench\n"
    ).encode()


def run_sync(source: Path, target: Path, *extra: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        [sys.executable, str(SCRIPT), str(source), "--target", str(target), *extra],
        capture_output=True, text=True, cwd=REPO)


def test_import_is_byte_identical_and_checkable(tmp_path):
    source = tmp_path / "leaderboard.yml"
    target = tmp_path / "session_bench.yml"
    source.write_bytes(canonical_artifact())

    imported = run_sync(source, target)
    assert imported.returncode == 0, imported.stderr
    assert target.read_bytes() == source.read_bytes()

    checked = run_sync(source, target, "--check")
    assert checked.returncode == 0, checked.stderr
    assert "byte-identical" in checked.stdout


def test_check_rejects_stale_hosted_artifact(tmp_path):
    source = tmp_path / "leaderboard.yml"
    target = tmp_path / "session_bench.yml"
    source.write_bytes(canonical_artifact())
    target.write_text("stale\n")

    checked = run_sync(source, target, "--check")
    assert checked.returncode != 0
    assert "hosted artifact is stale" in checked.stderr


def test_rejects_agent_sessions_generated_artifact(tmp_path):
    source = tmp_path / "old.yml"
    target = tmp_path / "session_bench.yml"
    source.write_text(
        "# GENERATED by scripts/session_bench/evaluate.py — do not hand-edit.\n"
        "generated_by: scripts/session_bench/evaluate.py\n")

    imported = run_sync(source, target)
    assert imported.returncode != 0
    assert "not the canonical Session-Bench artifact" in imported.stderr
    assert not target.exists()


def test_checked_in_artifact_has_standalone_provenance():
    checked = run_sync(HOSTED, HOSTED, "--check")
    assert checked.returncode == 0, checked.stderr


def test_agent_sessions_has_no_benchmark_engine_directory():
    assert not (REPO / "scripts" / "session_bench").exists()
